private void xrLabel48_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {		
   if (GetCurrentColumnValue("DEBIMONBAZE") != null && GetCurrentColumnValue("KREDIMONBAZE").ToString() != "")
            {


                if (GetCurrentColumnValue("NIVELREGJISTRIMI").ToString() == "FSH" || GetCurrentColumnValue("NIVELREGJISTRIMI").ToString() == "ND" || GetCurrentColumnValue("NIVELREGJISTRIMI").ToString() == "VKF" || GetCurrentColumnValue("NIVELREGJISTRIMI").ToString() == "FB")
                    xrLabel48.Text = String.Format("{0:#,#.00}", vleraProgresive);
                else
                {
                    vleraProgresive = vleraProgresive + gjendjameparedebi - gjendjameparekredi;
                    if (filter_Monedha == "False")
                        vleraProgresive = vleraProgresive + Convert.ToDouble(GetCurrentColumnValue("DEBIMONBAZE").ToString()) - Convert.ToDouble(GetCurrentColumnValue("KREDIMONBAZE").ToString());
                    else vleraProgresive = vleraProgresive + Convert.ToDouble(GetCurrentColumnValue("DEBIMONLLOG").ToString()) - Convert.ToDouble(GetCurrentColumnValue("KREDIMONLLOG").ToString());
                    xrLabel48.Text = String.Format("{0:N2}", vleraProgresive);
                }


            }
}

