private void xrLabel74_SummaryGetResult(object sender, DevExpress.XtraReports.UI.SummaryGetResultEventArgs e) 
{
	if (fshMax < arketimeMax)
	{
		if (arketimeMax - vleraProgresive2 > 0)
			e.Result = String.Format("{0:N2}", arketimeMax - vleraProgresive2);
		else 
			e.Result  = 0.00;
	}
	else if(fshMax == arketimeMax)
	{
		if (vleraProgresive2 < 0)
			e.Result = String.Format("{0:N2}", Math.Abs(vleraProgresive2));
		else 
			e.Result  = 0.00;	
	}
	else
		e.Result  = 0.00;

	e.Handled = true;
}


