private void xrTableCell38_SummaryRowChanged(object sender, System.EventArgs e) 
{
	double temp = 0;
	if (filter_Monedha == "False")
	{
		if (GetCurrentColumnValue("GJENDJADEBI") != null && GetCurrentColumnValue("GJENDJAKREDI") != null)
		{
			if (Convert.ToDouble(GetCurrentColumnValue("GJENDJADEBI").ToString()) - Convert.ToDouble(GetCurrentColumnValue("GJENDJAKREDI").ToString()) <= 0)
			{
				temp = Convert.ToDouble(GetCurrentColumnValue("GJENDJAKREDI").ToString()) - Convert.ToDouble(GetCurrentColumnValue("GJENDJADEBI").ToString());
			}
		}
	}
	else
	{
		if (GetCurrentColumnValue("GjendjaDebiLlog") != null && GetCurrentColumnValue("GjendjaKrediLlog") != null)
		{
			if (Convert.ToDouble(GetCurrentColumnValue("GjendjaDebiLlog").ToString()) - Convert.ToDouble(GetCurrentColumnValue("GjendjaKrediLlog").ToString()) <= 0)
			{
				temp = Convert.ToDouble(GetCurrentColumnValue("GjendjaKrediLlog").ToString()) - Convert.ToDouble(GetCurrentColumnValue("GjendjaDebiLlog").ToString());
			}
		}
	}

	if (temp > arketimeMax)
		arketimeMax = temp;	
}

